{
  "status": "SUPPORTED",
  "task_summary": "Prepare living room with refreshment settings and accessible entertainment control.",
  "task_contract": {
    "functional_roles": [
      {
        "id": "refreshment_container",
        "entity_kind": "OBJECT",
        "function": "Holds refreshments for consumption.",
        "required_count": 2,
        "binding_policy": "DISTINCT"
      ,
        "candidate_categories": [
          "cup",
          "mug",
          "bowl",
          "plate"
        ],
        "required_properties": [
          "holds_liquid_or_food"
        ]
      },
      {
        "id": "entertainment_control",
        "entity_kind": "OBJECT",
        "function": "Operates the television or media system.",
        "required_count": 1,
        "binding_policy": "REUSABLE"
      ,
        "candidate_categories": [
          "remote_control",
          "media_controller"
        ],
        "required_properties": [
          "operates_electronics"
        ]
      },
      {
        "id": "surface",
        "entity_kind": "REGION",
        "function": "Supports objects and defines a placement location.",
        "required_count": 2,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": [
          "coffee_table",
          "side_table",
          "desk"
        ],
        "required_properties": [
          "flat",
          "stable",
          "supportive"
        ]
      },
      {
        "id": "seating_zone",
        "entity_kind": "REGION",
        "function": "Defines the area where people sit to enjoy refreshments.",
        "required_count": 1,
        "binding_policy": "SHARED"
      ,
        "candidate_categories": [
          "lounge_area",
          "seating_group"
        ],
        "required_properties": [
          "contains_seats",
          "facing_television"
        ]
      }
    ],
    "functional_relations": [
      {
        "id": "refreshment_placement",
        "relation": "Each refreshment container is placed on a surface within the seating zone.",
        "participant_roles": [
          "refreshment_container",
          "surface",
          "seating_zone"
        ]
      ,
        "required": true
      },
      {
        "id": "control_placement",
        "relation": "The entertainment control is placed on a surface within the seating zone.",
        "participant_roles": [
          "entertainment_control",
          "surface",
          "seating_zone"
        ]
      ,
        "required": true
      }
    ],
    "operation_pairings": [
      {
        "id": "provide_refreshment",
        "operation": "Place a refreshment container on a surface.",
        "participant_roles": [
          "refreshment_container",
          "surface"
        ]
      ,
        "operation_count": 2
      },
      {
        "id": "position_control",
        "operation": "Move the entertainment control to a surface.",
        "participant_roles": [
          "entertainment_control",
          "surface"
        ]
      ,
        "operation_count": 1
      }
    ]
  },
  "observation_guidance": {
    "visible_candidates_per_role": {
      "refreshment_container": [
        {
          "label": "red cups",
          "visual_description": "Two red cups sitting on the desk in the foreground."
        }
      ],
      "entertainment_control": [
        {
          "label": "remote",
          "visual_description": "A black remote control lying on the desk next to the cups."
        }
      ],
      "surface": [
        {
          "label": "coffee table",
          "visual_description": "A rectangular low table in the center of the room."
        },
        {
          "label": "side tables",
          "visual_description": "Small wooden tables flanking the armchairs."
        },
        {
          "label": "desk",
          "visual_description": "A large wooden desk in the foreground containing the cups and remote."
        }
      ],
      "seating_zone": [
        {
          "label": "seating group",
          "visual_description": "The area defined by two armchairs facing the television."
        }
      ]
    },
    "inspectable_regions": [],
    "inspection_order": []
  }
  ,
